/* 在启动看门狗之前清理残留配置 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_WWDG, ENABLE);
WWDG_DeInit();

/* 然后重新配置 */
WWDG_SetPrescaler(WWDG_Prescaler_8);
WWDG_SetWindowValue(0x5F);
WWDG_Enable(0x7F);

/* 典型配置：PCLK1 = 36MHz，分频 8
   计数步长 = 4096 * 8 / 36MHz = 0.91ms
   计数值 0x7F -> 0x3F 共 64 步 -> 约 58ms */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_WWDG, ENABLE);
WWDG_SetPrescaler(WWDG_Prescaler_8);
WWDG_SetWindowValue(0x50);
WWDG_Enable(0x7F);

/* 窗口配置：计数值必须落到 (0x3F, 0x50] 区间内喂狗才合法
   计数值 0x7F 时喂 -> 太早，复位
   计数值 0x45 时喂 -> 合法
   计数值降到 0x3F 以下 -> 太晚，复位 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_WWDG, ENABLE);
WWDG_SetPrescaler(WWDG_Prescaler_8);
WWDG_SetWindowValue(0x50);
WWDG_Enable(0x7F);

/* 通过 EWI 在复位前保存现场 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_WWDG, ENABLE);
WWDG_SetPrescaler(WWDG_Prescaler_8);
WWDG_SetWindowValue(0x50);
WWDG_EnableIT();                /* 使能提前唤醒中断 */
WWDG_Enable(0x7F);

/* NVIC 必须使能 WWDG_IRQn */
NVIC_InitTypeDef NVIC_InitStructure;
NVIC_InitStructure.NVIC_IRQChannel = WWDG_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 0x00;  /* 优先级要高 */
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0x00;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

void WWDG_IRQHandler(void)
{
  WWDG_ClearFlag();   /* 必须先清 EWI 标志 */

  /* 抢救数据：写进备份寄存器（先开备份域访问） */
  PWR_BackupAccessCmd(ENABLE);
  BKP_WriteBackupRegister(BKP_DR1, 0x0BAD);

  /* 选择一：喂狗继续跑 */
  WWDG_SetCounter(0x7F);
  /* 选择二：不再喂狗，等待 WWDG 复位 */
}

while (1)
{
  Task_Run();              /* 业务必须耗时落在合法窗口内 */
  WWDG_SetCounter(0x7F);   /* 喂狗：写回 0x7F */
}

/* WWDG 完整初始化：PCLK1 = 36MHz，分频 8，窗口 0x50 */
void WWDG_Config(void)
{
  RCC_APB1PeriphClockCmd(RCC_APB1Periph_WWDG, ENABLE);

  WWDG_SetPrescaler(WWDG_Prescaler_8);   /* 计数步长约 0.91ms */
  WWDG_SetWindowValue(0x50);             /* 上窗口：不能早于这个值喂 */
  WWDG_EnableIT();                       /* 提前唤醒中断，用于保存现场 */
  WWDG_Enable(0x7F);                     /* 启动，不可逆 */

  /* 调试时冻结 WWDG，避免断点被复位 */
  RCC_APB2PeriphClockCmd(RCC_APB2Periph_AFIO, ENABLE);
  DBGMCU_Config(DBGMCU_WWDG_STOP, ENABLE);
}

while (1)
{
  Task_Run();
  WWDG_SetCounter(0x7F);   /* 喂狗，注意时机要在窗口内 */
}

void WWDG_IRQHandler(void)
{
  if (WWDG_GetFlagStatus() != RESET)
  {
    WWDG_ClearFlag();       /* 必须先清标志，否则中断反复进入 */
    /* 此时计数器已到 0x40，马上要复位：抢救数据或喂狗 */
    WWDG_SetCounter(0x7F);  /* 若想继续运行就喂狗 */
  }
}

void WWDG_IRQHandler(void)
{
  WWDG_ClearFlag();   /* 第一件事就是清标志 */

  /* 然后在极短时间内做出决定：喂狗继续，或保存现场等待复位 */
  WWDG_SetCounter(0x7F);
}
